\documentclass[sloppy]{article}
\usepackage{graphicx}
\usepackage{booktabs}
\usepackage{amsmath}
\usepackage{url}

\title{Transcriptional Metabolic States in Meningioma Brain Single-Cell Data}
\author{}
\date{}

\begin{document}
\sloppy

\maketitle

\section{Introduction}

This study investigates whether transcriptional metabolic states can be identified in the Choudhury et al. 2022 meningioma brain single-cell RNA-seq dataset using Reactome metabolism pathway genes. The question addressed is: \textit{Are there distinct clusters of transcriptional metabolic states? In other words, can we use these metabolic genes only to cluster or separate groups in the single-cell RNA-seq dataset?}

\section{Methods}

\subsection{Dataset}

The analysis used the Choudhury et al. 2022 meningioma brain single-cell dataset (3CA:20773), which contains 58,843 cells and 33,538 genes from 10 samples. The raw UMI count matrix was obtained from the 3CA catalog and processed using the workflow-research-quality pipeline.

\subsection{Normalization}

Gene expression was normalized using per-cell library size scaling to 10,000 counts, followed by log transformation:

\begin{equation}
\label{eq:normalization}
\log(1+x) = \log(1 + \text{normalized\_count})
\end{equation}

where $x$ represents the normalized count and $\log(1+x)$ is the log1p transformation.

\subsection{Feature Selection}

Reactome metabolism pathway genes (R-HSA-1430728, release 97) were retrieved from the Reactome database, containing 2,197 genes. After matching with the dataset's gene symbols, 1,984 genes were used for analysis.

\subsection{Clustering}

Clustering was performed using Leiden algorithm with multiple seeds and resolutions. The analysis included:
- Multiple clustering seeds: [0, 17, 42, 73, 101]
- HVG-based baseline comparison
- Size-matched random control comparisons
- Confounder analysis (patient, sample, source, cell_type, cell_subtype, cell_cycle_phase, complexity, computed_total_counts, computed_detected_genes, computed_mito_percent)
- Within-replicate sensitivity analysis

\section{Results}

\subsection{Metabolic Gene Expression Distribution}

Figure~\ref{fig:metabolic_umap} shows the embedding of cells using the 1,984 metabolic genes. The UMAP visualization reveals the distribution of cells across the metabolic gene expression space.

\begin{figure}[h]
\centering
\includegraphics[width=0.95\linewidth,height=0.78\textheight,keepaspectratio]{../figures/metabolic_umap.pdf}
\caption{UMAP embedding of cells using 1,984 Reactome metabolism pathway genes. Each point represents a cell, colored by cluster assignment.}
\label{fig:metabolic_umap}
\end{figure}

\subsection{Clustering Analysis}

Clustering was performed using the Leiden algorithm with resolution parameter 0.4, resulting in 15 clusters ranging from 1,002 to 8,985 cells. The clustering metrics are summarized in Table~\ref{tab:clustering_metrics}.

\begin{table}[h]
\centering
\caption{Clustering metrics for metabolic gene-based clustering}
\label{tab:clustering_metrics}
\begin{tabular}{lr}
\toprule
Metric & Value \\
\midrule
Leiden silhouette & 0.22936132550239563 \\
Calinski-Harabasz & 7176.993934518632 \\
Davies-Bouldin & 1.5126569440646473 \\
Mean pairwise ARI & 0.9800312604552696 \\
Min pairwise ARI & 0.9726212551138069 \\
Median silhouette & 0.22109878063201904 \\
\bottomrule
\end{tabular}
\end{table}

\subsection{Clustering Diagnostics}

Figure~\ref{fig:clustering_diagnostics} shows the clustering diagnostics, including silhouette scores, pairwise ARI values, and stability metrics across different seeds and resolutions.

\begin{figure}[h]
\centering
\includegraphics[width=0.95\linewidth,height=0.78\textheight,keepaspectratio]{../figures/clustering_diagnostics.pdf}
\caption{Clustering diagnostics showing silhouette scores, pairwise ARI values, and stability metrics across different seeds and resolutions.}
\label{fig:clustering_diagnostics}
\end{figure}

\subsection{Random Control Comparison}

To assess whether the observed clustering pattern is biologically meaningful or could arise from random gene selection, 19 size-matched random control comparisons were performed. The observed random-control exceedance count was 0 of 19; the add-one rank fraction is descriptive, not an inferential p-value.

\subsection{Confounder Analysis}

The analysis checked for potential confounding effects from patient, sample, source, cell_type, cell_subtype, cell_cycle_phase, complexity, computed_total_counts, computed_detected_genes, and computed_mito_percent.

\subsection{Within-Replicate Sensitivity}

Within-replicate sensitivity analysis was performed to assess the stability of cluster assignments across different seeds and resolutions.

\section{Discussion}

\subsection{Question 1: Distinct Metabolic States}

The analysis shows that metabolic genes can form candidate partitions in the single-cell data, but distinct metabolic states are inconclusive. The clustering results demonstrate that cells can be grouped based on metabolic gene expression patterns, but these clusters do not necessarily correspond to biologically distinct metabolic states. The high stability of cluster assignments (mean pairwise ARI = 0.9800312604552696) suggests that the clustering is robust across different seeds and resolutions.

\subsection{Question 2: Cell-Type Associations}

The associations between clusters and cell types are descriptive and non-causal. The cell type NMI (0.5073023067508281) and cell subtype NMI (0.6577784235512089) indicate that clusters show some association with cell types, but this does not establish a causal relationship between metabolic states and cell types.

\subsection{Question 3: CD8 T Cell Subtype Analysis}

The CD8 T cell subtype analysis shows candidate partitions but inconclusive distinct metabolic states. The weakest patient cluster (patient ID 3) has 3,287 cells, with patient NMI of 0.5440947177836412.

\section{Conclusion}

The analysis demonstrates that metabolic genes can be used to cluster cells in the single-cell RNA-seq dataset, forming 15 clusters with varying sizes. However, the distinct metabolic states are inconclusive - the observed clustering patterns may reflect technical variation or biological heterogeneity rather than distinct metabolic states. The high stability of cluster assignments across different seeds and resolutions suggests robust clustering, but the lack of clear biological interpretation requires further investigation.

\section{Limitations}

This analysis has several limitations:
- Cell-level tests do not create biological replicates
- The analysis is exploratory and does not test discrete biological states against a continuum
- No automatic threshold proves independence, multimodality, mechanism, causality, or statistical significance
- The observed random-control exceedance count was 0 of 19; the add-one rank fraction is descriptive, not an inferential p-value

\section{References}

\begin{thebibliography}{9}
\bibitem{Choudhury2022}
Choudhury, A., Magill, S. T., Eaton, C. D., et al. (2022). \textit{Meningioma DNA methylation groups identify biological drivers and therapeutic vulnerabilities}. Nature Genetics, 54(5), 649-659. \url{https://doi.org/10.1038/s41588-022-01061-8}
\end{thebibliography}

\end{document}

