\bibitem{Choudhury2022}
Abrar Choudhury, Stephen T. Magill, Charlotte D. Eaton, Briana C. Prager, William C. Chen, Martha A. Cady, Kyounghee Seo, Calixto-Hope G. Lucas, Tim J. Casey-Clyde, Harish N. Vasudevan, S. John Liu, Javier E. Villanueva-Meyer, Tai-Chung Lam, Jenny Kan-Suen Pu, Lai-Fung Li, Gilberto Ka-Kit Leung, Danielle L. Swaney, Michael Y. Zhang, Jason W. Chan, Zhixin Qiu, Michael V. Martin, Matthew S. Susko, Steve E. Braunstein, Nancy Ann Oberheim, Jessica D. Schulte, Nicholas Butowski, Penny K. Sneed, Mitchel S. Berger, Nevan J. Krogan, Arie Perry, Joanna J. Phillips, David A. Solomon, Joseph F. Costello, Michael W. McDermott, Jeremy N. Rich, David R. Raleigh.
\title{Meningioma DNA methylation groups identify biological drivers and therapeutic vulnerabilities}
\journal{Nature Genetics}
\year{2022}
\volume{54}
\issue{5}
\pages{649--659}
\url{https://www.nature.com/articles/s41588-022-01061-8}
\end{thebibliography}

\end{document}

